begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
select ok(not (select enabled or voice_enabled or video_enabled or pre_match_enabled or provider_ready from private.connect_config),'all flags default off');
select is((select environment from private.connect_config),'unconfigured','environment fails closed');
select ok(not has_table_privilege('authenticated','private.connect_sessions','INSERT'),'cannot directly create call');
select ok(not has_table_privilege('authenticated','private.connect_sessions','UPDATE'),'cannot directly join or change state');
select ok(not has_table_privilege('authenticated','private.connect_sessions','SELECT'),'cannot read private call data');
select ok(not has_table_privilege('service_role','private.connect_grants','UPDATE'),'service cannot silently grant consent');
select ok(not has_function_privilege('authenticated','public.rpc_connect_reconcile_media(uuid,text,uuid[],boolean)','EXECUTE'),'client cannot certify media');
select ok(not has_function_privilege('authenticated','public.rpc_connect_claim_job()','EXECUTE'),'client cannot claim provider work');
select ok(not has_function_privilege('anon','public.rpc_connect_create_call(uuid,text,text,uuid,uuid,uuid)','EXECUTE'),'anonymous creation denied');
select ok(has_function_privilege('service_role','public.rpc_connect_claim_job()','EXECUTE'),'worker explicitly authorized');
select ok(not has_function_privilege('authenticated','private.connect_transition(uuid,text,text)','EXECUTE'),'private transition helper denied');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname like 'connect_%' and c.relkind='r' and not c.relrowsecurity),0::bigint,'all private tables use RLS');
select is((select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='private' and p.proname like 'connect_%' or n.nspname='public' and p.proname like 'rpc_connect_%') and not 'search_path=pg_catalog'=any(coalesce(p.proconfig,'{}'))),0::bigint,'all privileged functions fix search path');
select throws_ok($$update private.connect_config set environment='production',enabled=true,provider_ready=true$$,'23514',null,'production cannot be enabled');
set local role authenticated;
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.rpc_connect_get_history()$$,'42501','connect_unauthenticated','authenticated role without user rejected');
select * from finish();
rollback;
